void
doFrameBuffer (vector<half>& storage, const Header& hdr, FrameBuffer& dummy)
{

    int chans = 0;
    for (ChannelList::ConstIterator q = hdr.channels ().begin ();
         q != hdr.channels ().end ();
         q++)
    {
        chans++;
    }

    Box2i dw = hdr.dataWindow ();

    storage.resize ((dw.size ().x + 1) * (dw.size ().y + 1) * chans);

    int xstride = chans * sizeof (half);
    int ystride = xstride * (dw.size ().x + 1);
    int offset  = ystride * dw.min.y + dw.min.x * xstride;

    int chan = 0;
    for (ChannelList::ConstIterator q = hdr.channels ().begin ();
         q != hdr.channels ().end ();
         q++)
    {
        dummy.insert (
            q.name (),
            Slice (HALF, ((char*) &storage[chan]) - offset, xstride, ystride));
        chan++;
    }
}

template <class T>
void
readTiledThing (T& input, bool test)
{
    vector<half> value;
    FrameBuffer  dummy;
    doFrameBuffer (value, input.header (), dummy);
    input.setFrameBuffer (dummy);
    int x_levels;
    int y_levels;

    if (test && input.header ().hasType ())
    {
        if (input.header ().type () != TILEDIMAGE)
        {
            std::cerr << "tiled image/part didn't have tiledimage type\n";
            //assert(input.type()==TILEDIMAGE);
        }
    }

    TileDescription t = input.header ().tileDescription ();
    switch (t.mode)
    {
        case ONE_LEVEL:
            x_levels = 1;
            y_levels = 1;
            break;
        case MIPMAP_LEVELS:
            x_levels = input.numXLevels ();
            y_levels = 1;
            break;
        case RIPMAP_LEVELS:
            x_levels = input.numXLevels ();
            y_levels = input.numYLevels ();
            break;
        case NUM_LEVELMODES:
        default:
            std::cerr << "Invalid tile mode " << int (t.mode) << std::endl;
            x_levels = y_levels = 0;
            break;
    }
